import java.util.*;

class Solution {
    public String minRemoveToMakeValid(String s) {
        int n = s.length();
        boolean[] drop = new boolean[n];
        Deque<Integer> open = new ArrayDeque<>();  // indices of unpaired '('
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (c == '(') open.push(i);
            else if (c == ')') {
                if (open.isEmpty()) drop[i] = true;  // nothing to pair with
                else open.pop();
            }
        }
        while (!open.isEmpty()) drop[open.pop()] = true;  // '(' never closed
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) if (!drop[i]) sb.append(s.charAt(i));
        return sb.toString();
    }
}

