class Solution:
    def minRemoveToMakeValid(self, s: str) -> str:
        st = []; drop = set()
        for i, c in enumerate(s):
            if c == "(": st.append(i)
            elif c == ")":
                if st: st.pop()
                else: drop.add(i)
        drop.update(st)
        return "".join(c for i, c in enumerate(s) if i not in drop)

