function minRemoveToMakeValid(s) {
  // pass 1: drop unmatched ')'
  let out = [], open = 0;
  for (const c of s) { if (c === "(") { open++; out.push(c); } else if (c === ")") { if (open) { open--; out.push(c); } } else out.push(c); }
  // after pass 1 every ')' is matched; scanning right to left, a '(' with no pending ')' is unpaired
  const res = []; let close = 0;
  for (let i = out.length - 1; i >= 0; i--) { const c = out[i]; if (c === ")") close++; else if (c === "(") { if (!close) continue; close--; } res.push(c); }
  return res.reverse().join("");
}
